/**
 * Ward / commune data loader for all 63 Vietnamese provinces (pre-2025 structure).
 *
 * Data source: sub-vn npm package (GSO 2019 administrative data).
 * Generated by: scripts/build-vn-wards.mjs → public/wards/{provinceCode}.json
 *
 * Each JSON file is ~3–9 kB, fetched once per session and cached.
 * Only the selected province's file is ever loaded (lazy per province).
 */

// In-memory cache: provinceCode → { [districtCode]: string[] }
const cache = {};

/**
 * Load ward data for a province. Returns the district→wards map.
 * Uses the browser's native fetch so Vite doesn't bundle the JSON.
 */
async function loadProvince(provinceCode) {
  if (cache[provinceCode]) return cache[provinceCode];
  try {
    const res = await fetch(`/wards/${provinceCode}.json`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    cache[provinceCode] = await res.json();
  } catch {
    cache[provinceCode] = {};
  }
  return cache[provinceCode];
}

/**
 * Returns wards for the given province + district.
 * Resolves to [{ code, name }, ...] — same shape as before.
 */
export async function getWards(provinceCode, districtCode) {
  if (!provinceCode || !districtCode) return [];
  const distMap = await loadProvince(provinceCode);
  return (distMap[districtCode] || []).map((name) => ({ code: name, name }));
}
